cat > /tmp/b5.mjs <<'EOF'
import { writeFileSync } from 'node:fs';
const C=[];
const p=(inst,pat)=>C.push({a:JSON.stringify(inst),b:JSON.stringify({pattern:pat})});
// basic re.search semantics
p("abc","b");            // partial match -> valid
p("abc","^b");           // no
p("abc","^abc$");
p("abc","c$");
p("abc","^a");
p("abc","d");
p("a\nb","^b");          // multiline OFF -> fail
p("a\nb","(?m)^b");      // inline flag
p("a\nb","b$");          // $ before \n? re: $ matches at end or before trailing newline
p("a\nb\n","b$");
p("ab\n","b$");          // trailing newline -> $ matches
p("ab\n","^ab$");
p("ab\n\n","b$");
p("abc","a.c");
p("a\nc","a.c");         // DOTALL off
p("a\nc","(?s)a.c");
// \d \w \s unicode semantics (Python str patterns are UNICODE by default)
p("٣","\\d");            // ARABIC-INDIC DIGIT THREE
p("１","\\d");           // FULLWIDTH DIGIT ONE
p("é","\\w");
p("中","\\w");
p("_","\\w");
p(" ","\\s");       // NBSP
p(" ","\\s");       // EM SPACE
p("é","\\W");
p("٣","\\D");
p("A","(?a)\\w");
p("é","(?a)\\w");
p("٣","(?a)\\d");
// \A \Z
p("abc","\\Aabc\\Z");
p("abc\n","abc\\Z");
p("abc\n","abc\\z");
p("abc","\\babc\\b");
p("abc","\\Babc");
// named groups python style
p("abc","(?P<x>a)(?P=x)?bc");
p("aabc","(?P<x>a)(?P=x)bc");
p("aa","(?P<x>a)(?P=x)");
p("ab","(?P<x>a)(?P=x)");
p("abc","(?#comment)abc");
p("ABC","(?i)abc");
p("ABC","abc");
p("A\nB","(?im)^b");
p("abc","a(?i)BC");     // mid-pattern flag (deprecated in 3.11+?)
p("abc","(?i:AB)c");
p("ab","(?<=a)b");      // lookbehind
p("ab","(?<!x)b");
p("aaa","a{,3}");       // Python: {,3} == {0,3}
p("a{,3}","a{,3}");
p("a","a{2,}");
p("]","]");             // unescaped ] literal
p("{","{");             // unescaped { literal
p("a{","a{");
p("x","[[:alpha:]]");   // POSIX class NOT supported in Python -> char class of [:alph]
p("a","[[:alpha:]]");
p(":","[[:alpha:]]");
p("aaa","(?>a+)a");     // atomic group (Python 3.11+)
p("aaa","a++");         // possessive (Python 3.11+)
p("abcabc","(abc)\\1");
p("abc","\\N{LATIN SMALL LETTER A}bc");
writeFileSync('/tmp/cases/b5.json', JSON.stringify(C));
EOF
